package execution
import("context";"crypto/rand";"crypto/sha256";"encoding/hex";"errors";"sync";"time";"github.com/nevzatcirak/harness-bridge/internal/adapters/opencode")
type Runner interface{History(context.Context,string)([]opencode.Message,error);Status(context.Context)(map[string]opencode.Status,error);Prompt(context.Context,string,string,string)error;Abort(context.Context,string)error}
type Execution struct{ID string `json:"execution_id"`;SessionID string `json:"session_id"`;MessageID string `json:"message_id"`;State string `json:"state"`;Error string `json:"error,omitempty"`;Updated time.Time `json:"updated_at"`;Baseline map[string]bool `json:"-"`}
type Manager struct{mu sync.Mutex;r Runner;runs map[string]*Execution;busy map[string]string;keys map[string]string;fingerprints map[string][32]byte}
func New(r Runner)*Manager{return &Manager{r:r,runs:map[string]*Execution{},busy:map[string]string{},keys:map[string]string{},fingerprints:map[string][32]byte{}}}
func token()(string,error){b:=make([]byte,16);if _,e:=rand.Read(b);e!=nil{return "",e};return hex.EncodeToString(b),nil}
func(m *Manager)Send(ctx context.Context,session,prompt,key string)(Execution,error){if session==""||prompt==""||key==""{return Execution{},errors.New("missing required input")};m.mu.Lock();defer m.mu.Unlock();k:=session+"\x00"+key;hash:=sha256.Sum256([]byte(prompt));if id,ok:=m.keys[k];ok{if m.fingerprints[k]!=hash{return Execution{},errors.New("idempotency key conflict")};return *m.runs[id],nil};if m.busy[session]!=""{return Execution{},errors.New("session busy")};status,e:=m.r.Status(ctx);if e!=nil{return Execution{},e};if s,ok:=status[session];ok&&s.Type!="idle"{return Execution{},errors.New("native session busy")};history,e:=m.r.History(ctx,session);if e!=nil{return Execution{},e};baseline:=map[string]bool{};for _,msg:=range history{baseline[msg.Info.ID]=true};id,e:=token();if e!=nil{return Execution{},e};mid,e:=token();if e!=nil{return Execution{},e};x:=&Execution{ID:id,SessionID:session,MessageID:mid,State:"submitting",Updated:time.Now().UTC(),Baseline:baseline};m.runs[id]=x;m.busy[session]=id;m.keys[k]=id;m.fingerprints[k]=hash;if e=m.r.Prompt(ctx,session,prompt,mid);e!=nil{x.State="unknown";x.Error=e.Error();return *x,e};x.State="running";return *x,nil}
func(m *Manager)Get(ctx context.Context,id string)(Execution,error){m.mu.Lock();defer m.mu.Unlock();x:=m.runs[id];if x==nil{return Execution{},errors.New("execution not found")};if x.State!="running"{return *x,nil};statuses,e:=m.r.Status(ctx);if e!=nil{x.State="unknown";x.Error=e.Error();return *x,nil};s,exists:=statuses[x.SessionID];if !exists{x.State="unknown";x.Error="native status absent";return *x,nil};if s.Type=="idle"{messages,e:=m.r.History(ctx,x.SessionID);if e!=nil{return *x,nil};for _,msg:=range messages{if msg.Info.Role=="assistant"&&!x.Baseline[msg.Info.ID]&&msg.Info.ID!=""{x.State="completed";if len(msg.Info.Error)>0&&string(msg.Info.Error)!="null"{x.State="failed"};delete(m.busy,x.SessionID);break}}};x.Updated=time.Now().UTC();return *x,nil}
func(m *Manager)Result(ctx context.Context,id string)(Execution,[]opencode.Message,error){x,e:=m.Get(ctx,id);if e!=nil{return x,nil,e};if x.State!="completed"&&x.State!="failed"{return x,nil,nil};msgs,e:=m.r.History(ctx,x.SessionID);if e!=nil{return x,nil,e};var result []opencode.Message;for _,msg:=range msgs{if !x.Baseline[msg.Info.ID]{result=append(result,msg)}};return x,result,nil}
func(m *Manager)Interrupt(ctx context.Context,id string)(Execution,error){m.mu.Lock();defer m.mu.Unlock();x:=m.runs[id];if x==nil{return Execution{},errors.New("execution not found")};if x.State!="running"{return *x,errors.New("not running")};if e:=m.r.Abort(ctx,x.SessionID);e!=nil{x.State="unknown";return *x,e};x.State="interrupted";delete(m.busy,x.SessionID);return *x,nil}
